const addLineNumbers = new Transform({
  transform(chunk, encoding, callback) {
    const lines = chunk.toString().split('\n');
    const numbered = lines.map((line, i) => `${i + 1}: ${line}`).join('\n');
    callback(null, numbered);
  }
});

